+fn same_program(a: &str, b: &str) -> bool {
+    let num = |w: &str| w.trim_start_matches(['A', 'B', 'C']).parse::<i64>().ok();
+    let word = |(x, y): (&str, &str)| match (num(x), num(y)) {
