+    let out = std::env::temp_dir().join(format!("camcraft-wire-tol-{tag}-{}.nc", std::process::id()));
+    let posted = posting::post_script(world, &out, cps);
+    let wrote = out.exists();
+    let _ = std::fs::remove_file(&out);
