+/// One plane's ends of the rulings: where each stands on the parallel
+/// at the kerf offset, its group (ends sharing one point), and each
+/// group's offset vector and scale.
+struct Ends {
+    base: Vec<Point2>,
+    group: Vec<usize>,
+    off: Vec<(f64, f64)>,
+    scale: Vec<f64>,
