+        let last = off.len().saturating_sub(1);
+        if last > 0 && base.first().zip(base.last()).is_some_and(|(a, b)| dist(*a, *b) <= SAME) {
+            group.iter_mut().filter(|g| **g == last).for_each(|g| *g = 0);
