+    /// Ruling `i`'s end as widened.
+    fn at(&self, i: usize) -> Point2 {
+        let g = self.group[i];
+        let (s, o) = (self.scale[g] - 1.0, self.off[g]);
+        Point2::new(self.base[i].x + s * o.0, self.base[i].y + s * o.1)
